//! Pure helpers for `/init` and `/export`: AGENTS.md template + session Markdown rendering.
//!
//! Kept as I/O-free pure functions for unit testing; file reads/writes are done by host methods in [`crate::slash`].

use starriver_kernel::types::{ContentBlock, Message, Role};

/// The AGENTS.md skeleton generated by `/init` (users may customize per project).
pub const AGENTS_MD_TEMPLATE: &str = "# Project Guide

Edit this file to give the coding agent project-specific instructions:

- Build / test commands
- Code conventions
- Key directories and entry points

The agent's own configuration lives in its AGENT.md (under `~/.starriver/agents/`).
";

/// Render session messages into a Markdown transcript. Only text content is expanded; tool calls/results are kept inline.
pub fn render_session_markdown(messages: &[Message]) -> String {
    let mut out = String::from("# Session transcript\n\n");
    for m in messages {
        let role = match m.role {
            Role::System => "system",
            Role::User => "user",
            Role::Assistant => "assistant",
            Role::Tool => "tool",
        };
        let mut parts: Vec<String> = Vec::new();
        for b in &m.content {
            match b {
                ContentBlock::Text { text } => parts.push(text.clone()),
                ContentBlock::Thinking { text } => parts.push(format!("*[thinking]* {text}")),
                ContentBlock::ToolUse { name, input, .. } => {
                    parts.push(format!("**tool {name}** `{input}`"));
                }
                ContentBlock::ToolResult {
                    content, is_error, ..
                } => {
                    let tag = if *is_error {
                        "**tool error**"
                    } else {
                        "tool result"
                    };
                    parts.push(format!("{tag} {content}"));
                }
            }
        }
        out.push_str(&format!("## {role}\n\n{}\n\n", parts.join("\n")));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn template_is_non_empty_and_instructive() {
        assert!(AGENTS_MD_TEMPLATE.contains("Project Guide"));
        assert!(AGENTS_MD_TEMPLATE.contains("AGENT.md"));
    }

    #[test]
    fn render_marks_roles_and_blocks() {
        let msgs = vec![
            Message::user("加个函数"),
            Message {
                meta: None,
                role: Role::Assistant,
                content: vec![ContentBlock::ToolUse {
                    id: "t1".into(),
                    name: "edit".into(),
                    input: serde_json::json!({"path": "a.rs"}),
                }],
            },
            Message::tool_result("t1", "ok", false),
        ];
        let md = render_session_markdown(&msgs);
        assert!(md.contains("## user"));
        assert!(md.contains("加个函数"));
        assert!(md.contains("**tool edit**"));
        assert!(md.contains("tool result ok"));
    }
}
